validator:
function validate(input) {
  const [{ Trips = [], Users = [] }] = input;
  const roles = new Map(), trips = new Set();
  for (const [id, banned, role] of Users) {
    if (id === null) return 'Every user needs a users_id.';
    if (roles.has(id)) return `users_id ${id} appears twice in Users.`;
    if (banned !== 'Yes' && banned !== 'No') return `banned must be 'Yes' or 'No' (user ${id}).`;
    if (!['client', 'driver', 'partner'].includes(role)) return `role of user ${id} must be client, driver or partner.`;
    roles.set(id, role);
  }
  for (const [id, client, driver, , status, day] of Trips) {
    if (id === null) return 'Every trip needs an id.';
    if (trips.has(id)) return `id ${id} appears twice in Trips.`;
    trips.add(id);
    if (!roles.has(client)) return `Trip ${id}: client_id ${client} is not in Users.`;
    if (!roles.has(driver)) return `Trip ${id}: driver_id ${driver} is not in Users.`;
    if (!['completed', 'cancelled_by_driver', 'cancelled_by_client'].includes(status)) return `Trip ${id} has an unknown status.`;
    if (typeof day !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(day)) return `Trip ${id}: request_at must be YYYY-MM-DD.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const statuses = ['completed', 'completed', 'cancelled_by_driver', 'cancelled_by_client'];
  const small = size === 'small';
  const days = small ? ['2013-09-30', '2013-10-01', '2013-10-02', '2013-10-03', '2013-10-04', '2013-10-01', '2013-10-02', '2013-10-03']
    : ['2013-09-29', '2013-09-30', '2013-10-01', '2013-10-02', '2013-10-03', '2013-10-04', '2013-10-05'];
  const clients = small ? 1 + pick(3) : 300, drivers = small ? 1 + pick(3) : 300, partners = small ? pick(2) : 20;
  const banRate = small ? 0.3 : 0.1;
  const Users = [], clientIds = [], driverIds = [];
  for (let i = 1; i <= clients; i++) { clientIds.push(i); Users.push([i, rand() < banRate ? 'Yes' : 'No', 'client']); }
  for (let i = 1; i <= drivers; i++) { driverIds.push(1000 + i); Users.push([1000 + i, rand() < banRate ? 'Yes' : 'No', 'driver']); }
  for (let i = 1; i <= partners; i++) Users.push([5000 + i, rand() < 0.5 ? 'Yes' : 'No', 'partner']);
  // Users are listed in a shuffled order so nothing depends on it.
  for (let i = Users.length - 1; i > 0; i--) { const j = pick(i + 1); [Users[i], Users[j]] = [Users[j], Users[i]]; }
  const count = small ? pick(9) : 2000, Trips = [];
  for (let id = 1; id <= count; id++) {
    Trips.push([id, clientIds[pick(clientIds.length)], driverIds[pick(driverIds.length)], 1 + pick(small ? 3 : 20), statuses[pick(statuses.length)], days[pick(days.length)]]);
  }
  return [{ Trips, Users }];
}
